## Why This Is Asked

Tests offline-first caching, atomic disk writes, and SwiftUI grid rendering with a testable data layer.

## Key Concepts

- SwiftUI LazyVGrid for gallery
- URLSession data tasks for image fetch
- FileManager and atomic writes to Documents cache
- Codable parsing of bundled JSON
- Persistence across restarts and simple unit tests

## Code Example

```swift
import Foundation
import SwiftUI

struct ImageItem: Decodable { let id: String; let url: String }

class GalleryVM: ObservableObject {
    @Published var items: [ImageItem] = []
    let cacheDir: URL = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0].appendingPathComponent("imageCache")

    init() { loadMetadata() }

    func loadMetadata() {
        // load from Bundle JSON (omitted for brevity)
    }

    func localPath(for id: String) -> URL {
        cacheDir.appendingPathComponent("\(id).jpg")
    }

    func fetchIfNeeded(item: ImageItem) async {
        let path = localPath(for: item.id)
        if FileManager.default.fileExists(atPath: path.path) { return }
        guard let url = URL(string: item.url) else { return }
        let (data, _) = try! await URLSession.shared.data(from: url)
        // write atomically
        let tmp = path.appendingPathExtension("tmp")
        try! data.write(to: tmp)
        try! FileManager.default.moveItem(at: tmp, to: path)
        await MainActor.run { self.objectWillChange.send() }
    }
}
```

